  return (
    <html
      lang="en"
      className={`${display.variable} ${ui.variable} ${time.variable} h-full antialiased`}
    >
      <body className="min-h-full flex flex-col bg-paper text-ink">
        <TopBar />
        <main className="flex-1">{children}</main>
      </body>
    </html>
  );
}

