import { getMeeting } from "@/lib/data";
import { notFound } from "next/navigation";
import { ClipPlayer } from "@/components/share/ClipPlayer";
import { fmtDate, mmss } from "@/lib/time";

export function generateStaticParams() {
  return [{ meetingId: "q3-roadmap" }, { meetingId: "ridgeline-discovery" }, { meetingId: "interview-lena" }, { meetingId: "helmar-checkin" }, { meetingId: "solo-test" }, { meetingId: "1on1-maya" }, { meetingId: "sprint-24-retro" }];
}

/** A clip page is served to people who were never on the call — no account, no other meetings. */
export default async function SharePage({
  params,
  searchParams,
}: {
  params: Promise<{ meetingId: string }>;
  searchParams: Promise<{ h?: string }>;
}) {
  const { meetingId } = await params;
  const { h: highlightId } = await searchParams;
  const meeting = getMeeting(meetingId);
  if (!meeting) notFound();
  const hl = meeting.highlights.find((x) => x.id === highlightId);

  return (
    <div className="mx-auto max-w-2xl px-4 py-12 sm:px-6">
      <header className="mb-8 flex items-baseline justify-between">
        <p className="flex items-baseline gap-1 text-lg">
          <span className="font-[family-name:var(--font-display)] font-semibold tracking-tight">
            Minutes
          </span>
          <span className="rec-dot size-1.5 translate-y-[-2px] rounded-full bg-record" aria-hidden />
        </p>
        <p className="text-[13px] text-ink-soft">A clip was shared with you</p>
      </header>

      {hl ? (
        <article>
          <p className="eyebrow mb-2">
            {fmtDate(meeting.startedAt)} · {fmtClipLen(hl)}
          </p>
          <h1 className="font-[family-name:var(--font-display)] text-3xl font-medium leading-tight tracking-tight">
            {hl.title}
          </h1>
          {hl.note && <p className="mt-2 text-[15px] leading-relaxed text-ink-soft">{hl.note}</p>}
          <div className="mt-6">
            <ClipPlayer meeting={meeting} start={hl.at} length={30} />
          </div>
          <section className="mt-6" aria-label="Words said in this clip">
            <h2 className="eyebrow mb-2">What was said here</h2>
            <ul className="space-y-2">
              {meeting.transcript
                .filter((u) => u.t + u.dur > hl.at - 2 && u.t < hl.at + 32)
                .map((u, i) => {
                  const sp = meeting.speakers.find((s) => s.id === u.speaker);
                  return (
                    <li key={i} className="flex gap-2.5 text-[14px] leading-relaxed">
                      <span className="mt-px shrink-0 font-mono text-[11px] text-ink-faint tabular-nums">
                        {mmss(u.t)}
                      </span>
                      <p>
                        <span className="font-semibold" style={{ color: sp?.color }}>
                          {sp?.name}
                        </span>
                        <span className="mx-1.5 text-line">|</span>
                        <span className="text-ink-soft">{u.text}</span>
                      </p>
                    </li>
                  );
                })}
            </ul>
          </section>
          <p className="mt-8 rounded-lg border border-line-soft bg-raised px-4 py-3 text-[13px] leading-relaxed text-ink-soft">
            This clip is all you can see — the rest of the meeting stays with{" "}
            {meeting.speakers.filter((s) => s.self).at(0)?.name ?? "the host"}
            . Recording and full transcript are available to people who were on the call.
          </p>
        </article>
      ) : (
        <p className="text-ink-faint">This clip link is missing or was revoked.</p>
      )}

      <footer className="mt-10 border-t border-line pt-4 text-[12px] text-ink-faint">
        Synthesized audio bed — this demo build stubs the capture layer (see the walkthrough).
      </footer>
    </div>
  );
}

function fmtClipLen(hl: { at: number }): string {
  return `starts ${Math.floor(hl.at / 60)}:${String(Math.floor(hl.at % 60)).padStart(2, "0")}`;
}

import { notFound } from "next/navigation";
import { allMeetings, getMeeting } from "@/lib/data";
import { MeetingView } from "@/components/meeting/MeetingView";

export function generateStaticParams() {
  // prerender every seeded meeting so the first open of any link is instant
  return allMeetings().map((m) => ({ id: m.id }));
}

export default async function MeetingPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ t?: string }>;
}) {
  const { id } = await params;
  const { t } = await searchParams;
  const meeting = getMeeting(id);
  if (!meeting) notFound();
  const initialTime = t ? Math.max(0, Math.min(meeting.duration, Math.floor(Number(t) || 0))) : 0;
  return <MeetingView meeting={meeting} initialTime={initialTime} />;
}

"use client";

import type { Meeting } from "@/lib/model";
import { usePlayer } from "@/lib/player";
import { Player } from "./Player";
import { TranscriptPane } from "./TranscriptPane";
import { LeftPanel } from "./LeftPanel";
import { fmtDate, fmtTime, hms } from "@/lib/time";
import { useEffect, useState } from "react";

export function MeetingView({ meeting, initialTime }: { meeting: Meeting; initialTime: number }) {
  const player = usePlayer(meeting, initialTime);
  const [copiedLink, setCopiedLink] = useState(false);

  // keyboard: space = play/pause, arrows seek (when not typing)
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      const tag = (e.target as HTMLElement)?.tagName;
      if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT") return;
      if (e.code === "Space") {
        e.preventDefault();
        player.toggle();
      }
      if (e.key === "ArrowRight") player.seek(player.t + 10);
      if (e.key === "ArrowLeft") player.seek(player.t - 10);
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [player]);

  async function copyAtCurrentTime() {
    const url = `${window.location.origin}/m/${meeting.id}?t=${Math.floor(player.t)}`;
    try {
      await navigator.clipboard.writeText(url);
      setCopiedLink(true);
      setTimeout(() => setCopiedLink(false), 2000);
    } catch {
      setCopiedLink(false);
    }
  }

  const others = meeting.speakers.filter((s) => !s.self);

  return (
    <div className="mx-auto max-w-6xl px-4 pb-16 pt-8 sm:px-6">
      {/* ── header ─────────────────────────────────────────────────────── */}
      <div className="mb-6 flex flex-wrap items-start justify-between gap-4">
        <div className="min-w-0">
          <h1 className="font-[family-name:var(--font-display)] text-[32px] font-medium leading-tight tracking-tight">
            {meeting.title}
          </h1>
          <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 text-[13.5px] text-ink-soft">
            <span>
              {fmtDate(meeting.startedAt)} · {fmtTime(meeting.startedAt)}
            </span>
            <span className="font-mono tabular-nums text-ink-faint">{hms(meeting.duration)}</span>
            <span>{meeting.platform}</span>
            <span
              className={
                "rounded-full px-2 py-0.5 text-[11.5px] font-medium " +
                (meeting.captureMode === "bot"
                  ? "bg-line-soft text-ink-soft"
                  : "bg-ok-soft text-ok")
              }
            >
              {meeting.captureMode === "bot" ? "bot recorded" : "bot-free capture"}
            </span>
          </div>
          <div className="mt-2 flex items-center gap-1.5 text-[13px] text-ink-soft">
            <span className="inline-flex -space-x-1.5" aria-hidden>
              {others.slice(0, 8).map((s) => (
                <span
                  key={s.id}
                  className="inline-block size-2.5 rounded-full ring-2 ring-paper"
                  style={{ background: s.color }}
                />
              ))}
            </span>
            <span>
              {others.map((s) => s.name.split(" ")[0]).join(", ")}
              {others.length === 0 ? " solo test" : ""}
            </span>
          </div>
        </div>
        <div className="flex shrink-0 gap-2">
          <button
            onClick={copyAtCurrentTime}
            className="rounded-full border border-line bg-raised px-3.5 py-2 text-[13px] font-medium text-ink-soft hover:border-ink-soft hover:text-ink"
          >
            {copiedLink ? "Link copied" : "Copy link to this moment"}
          </button>
        </div>
      </div>

      {/* ── panes ──────────────────────────────────────────────────────── */}
      <div className="grid grid-cols-1 items-start gap-8 lg:grid-cols-[minmax(0,1fr)_400px] xl:grid-cols-[minmax(0,1fr)_440px]">
        <div className="min-w-0 space-y-6">
          <Player meeting={meeting} player={player} />
          <LeftPanel meeting={meeting} player={player} />
        </div>
        <div className="lg:sticky lg:top-[72px] lg:h-[calc(100vh-88px)]">
          <TranscriptPane meeting={meeting} player={player} />
        </div>
      </div>
    </div>
  );
}

"use client";

import type { Meeting } from "@/lib/model";
import type { usePlayer } from "@/lib/player";
import { useState } from "react";
import { mmss } from "@/lib/time";

type Entry = {
  q: string;
  answer: string;
  cites: { t: number; text: string; who: string; color: string }[];
};

const STOP = new Set(["what", "was", "the", "did", "who", "how", "why", "is", "are", "we", "our", "a", "an", "to", "for", "said", "about", "decide", "decided", "think", "when", "of", "on", "in", "with", "@"]);

/**
 * "Ask this call" — retrieval over the transcript. Every claim in the answer is
 * a citation chip that jumps the recording to the exact moment, which is the
 * feature this build refuses to hide behind a paywall.
 */
export function AskPanel({
  meeting,
  player,
}: {
  meeting: Meeting;
  player: ReturnType<typeof usePlayer>;
}) {
  const [q, setQ] = useState("");
  const [entries, setEntries] = useState<Entry[]>([]);
  const [busy, setBusy] = useState(false);

  function ask(qu: string) {
    const query = qu.trim();
    if (!query || busy) return;
    setBusy(true);
    // retrieval: score utterances by term overlap
    const terms = query
      .toLowerCase()
      .replace(/[^a-z0-9% ]/g, "")
      .split(/\s+/)
      .filter((w) => w.length > 2 && !STOP.has(w));
    const scored = meeting.transcript
      .map((u) => {
        const l = u.text.toLowerCase();
        let score = 0;
        for (const term of terms) if (l.includes(term)) score += 1;
        return { u, score };
      })
      .filter((x) => x.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, 3);

    const sp = (id: string) => meeting.speakers.find((s) => s.id === id);
    setTimeout(() => {
      if (scored.length === 0) {
        setEntries((e) => [
          ...e,
          {
            q: query,
            answer:
              "Nothing in this call matches that. Try a phrase someone actually said — or switch to cross-meeting Search, which reads every call.",
            cites: [],
          },
        ]);
      } else {
        const answer =
          "Here's what was said, closest first:" +
          scored
            .map((s) => ` ${s.u.text}`)
            .join("")
            .replace(/\. /g, ". ")
            .slice(0, 0); // answer is rendered as the citation list itself
        void answer;
        setEntries((e) => [
          ...e,
          {
            q: query,
            answer: scored.length > 1 ? "What was said, closest first — every line plays from where it was said:" : "What was said — it plays from that moment:",
            cites: scored.map((s) => ({
              t: s.u.t,
              text: s.u.text,
              who: sp(s.u.speaker)?.name ?? "Unknown",
              color: sp(s.u.speaker)?.color ?? "#888",
            })),
          },
        ]);
      }
      setBusy(false);
      setQ("");
    }, 350);
  }

  return (
    <div>
      <p className="mb-3 text-[13px] text-ink-faint">
        Ask anything about this call in plain words. Answers are retrieved from the transcript — nothing is generated that can&rsquo;t be played back.
      </p>

      {entries.length > 0 && (
        <ul className="mb-4 space-y-4">
          {entries.map((en, i) => (
            <li key={i}>
              <p className="mb-1.5 text-[13.5px] font-semibold">{en.q}</p>
              <p className="mb-2 text-[13.5px] text-ink-soft">{en.answer}</p>
              <ul className="space-y-2">
                {en.cites.map((c, j) => (
                  <li key={j} className="flex gap-2.5 rounded-lg border border-line-soft bg-paper px-3 py-2">
                    <button
                      onClick={() => player.seek(c.t)}
                      className="mt-px h-fit shrink-0 rounded bg-record-soft px-1.5 py-px font-mono text-[11px] font-medium text-record tabular-nums hover:bg-record hover:text-paper"
                    >
                      {mmss(c.t)}
                    </button>
                    <p className="text-[13.5px] leading-snug text-ink-soft">
                      <span className="font-semibold" style={{ color: c.color }}>
                        {c.who}
                      </span>
                      <span className="mx-1 text-line">—</span>
                      {c.text}
                    </p>
                  </li>
                ))}
              </ul>
            </li>
          ))}
        </ul>
      )}

      <form
        onSubmit={(e) => {
          e.preventDefault();
          ask(q);
        }}
        className="flex gap-2"
      >
        <input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder={
            meeting.id === "q3-roadmap"
              ? "e.g. what did we decide about pricing?"
              : "Ask about what was said…"
          }
          className="min-w-0 flex-1 rounded-full border border-line bg-paper px-4 py-2 text-[14px] focus:outline-none"
          aria-label="Ask this call"
        />
        <button
          type="submit"
          disabled={busy}
          className="shrink-0 rounded-full bg-ink px-4 py-2 text-[13.5px] font-medium text-paper hover:opacity-90 disabled:opacity-50"
        >
          {busy ? "Looking…" : "Ask"}
        </button>
      </form>
    </div>
  );
}

"use client";

import type { Meeting } from "@/lib/model";
import { useEffect } from "react";
import { fmtDate } from "@/lib/time";

/**
 * Clip-share modal — the "share with someone who wasn't on the call" flow.
 * Creates a standalone link that plays just this moment and shows its words.
 */
export function ShareModal({
  meeting,
  highlightId,
  onClose,
}: {
  meeting: Meeting;
  highlightId: string;
  onClose: () => void;
}) {
  const h = meeting.highlights.find((x) => x.id === highlightId);
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") onClose();
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  if (!h) return null;
  const url =
    typeof window !== "undefined"
      ? `${window.location.origin}/share/${meeting.id}?h=${h.id}`
      : `/share/${meeting.id}?h=${h.id}`;

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-ink/40 p-4"
      role="dialog"
      aria-modal="true"
      aria-label="Share clip"
      onClick={onClose}
    >
      <div
        className="w-full max-w-md rounded-xl border border-line bg-raised p-5 shadow-xl"
        onClick={(e) => e.stopPropagation()}
      >
        <h2 className="font-[family-name:var(--font-display)] text-xl font-medium tracking-tight">
          Share this clip
        </h2>
        <p className="mt-1 text-[13.5px] leading-relaxed text-ink-soft">
          Anyone with this link can watch the moment from{" "}
          <span className="font-mono text-[12px] tabular-nums">{fmtClipTime(h.at)}</span> and
          read the words — no account needed. They won&rsquo;t see your other meetings.
        </p>

        <div className="mt-4 rounded-lg border border-line-soft bg-paper p-3">
          <p className="text-[13px] font-medium">{h.title}</p>
          <p className="mt-0.5 text-[12px] text-ink-faint">
            {meeting.title} · {fmtDate(meeting.startedAt)}
          </p>
        </div>

        <div className="mt-4 flex items-center gap-2">
          <input
            readOnly
            value={url}
            className="min-w-0 flex-1 rounded-md border border-line bg-paper px-3 py-2 font-mono text-[12px] text-ink-soft"
            aria-label="Shareable link"
            onFocus={(e) => e.target.select()}
          />
          <button
            onClick={() => navigator.clipboard?.writeText(url)}
            className="shrink-0 rounded-full bg-ink px-4 py-2 text-[13px] font-medium text-paper hover:opacity-90"
          >
            Copy link
          </button>
        </div>
        <div className="mt-3 flex justify-between">
          <a
            href={url}
            target="_blank"
            rel="noreferrer"
            className="text-[13px] font-medium text-record underline underline-offset-2"
          >
            Open what they&rsquo;ll see
          </a>
          <button onClick={onClose} className="text-[13px] text-ink-soft hover:text-ink">
            Done
          </button>
        </div>
      </div>
    </div>
  );
}

function fmtClipTime(t: number): string {
  return `${Math.floor(t / 60)}:${String(Math.floor(t % 60)).padStart(2, "0")}`;
}

